using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class PlayerDiceHandHolder : ReferenceSingleton<PlayerDiceHandHolder>
{
	[Header("Events")]
	[SerializeField]
	private StringEvent OnUpdateDrawAmountText;

	[Header("Debug")]
	[SerializeField]
	private bool verbose;

	[ShowNonSerializedField]
	private int drawDicesAmount;

	[ShowNonSerializedField]
	private int drawDicesAmountModifier;

	public List<DiceInstance> handDices = new List<DiceInstance>();

	public List<Dice> HandDicePreview = new List<Dice>();

	private List<ActionValueModifier> actionValueModifiers = new List<ActionValueModifier>();

	private CurrentCorruptedAnimals currentCorruptedAnimals => ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals;

	private CurrentCompanions currentCompanions => ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions;

	public int DefaultDrawDicesAmount => ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.DefaultDrawDiceAmount;

	public List<ActionValueModifier> ActionValueModifiers => actionValueModifiers;

	public int GetDiceInHandAmount()
	{
		return handDices.Count;
	}

	public DiceInstance GetDiceInstanceFromHand(int index)
	{
		return handDices[index];
	}

	public int GetDiceInHandAmountForgeable()
	{
		int num = 0;
		for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count; i++)
		{
			if (!ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices[i].ActionFace.BattleAction.NonForgeable)
			{
				num++;
			}
		}
		return num;
	}

	public int GetDiceInHandAmountNotLocked()
	{
		int num = 0;
		for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count; i++)
		{
			if (!ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices[i].ActionFace.BattleAction.Locked)
			{
				num++;
			}
		}
		return num;
	}

	public void AddDiceInstanceToHand(DiceInstance instance, Dice dice)
	{
		handDices.Add(instance);
		HandDicePreview.Add(dice);
	}

	public void RemoveDiceFromHand(DiceInstance instance)
	{
		handDices.Remove(instance);
		HandDicePreview.Remove(instance.Dice);
	}

	public void InitializeBattle()
	{
		SetDefaultDrawDicesAmount();
		actionValueModifiers.Clear();
		UpdateLinkEmpower();
		handDices.Clear();
		HandDicePreview.Clear();
	}

	private void UpdateLinkEmpower()
	{
		ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().UpdateLinkEmpower();
	}

	public void ModifyDrawDicesAmountModifier(int amount)
	{
		drawDicesAmountModifier += amount;
	}

	public int GetDrawDiceAmountWithOmensModifiers()
	{
		int num = 0;
		num += ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.GetDrawAdditionalDieAmountOmens();
		num += drawDicesAmountModifier;
		for (int i = 0; i < currentCorruptedAnimals.activeCorruptedAnimals.Count && !(currentCorruptedAnimals.activeCorruptedAnimals[i] == null); i++)
		{
			if (currentCorruptedAnimals.activeCorruptedAnimals[i].GetComponent<CorruptedAnimalEffects>().IsParalyzingAuraActive())
			{
				num--;
			}
		}
		for (int j = 0; j < currentCompanions.ActiveCompanions.Count && !(currentCompanions.ActiveCompanions[j] == null); j++)
		{
			int num2 = currentCompanions.ActiveCompanions[j].GetComponent<CompanionEffects>().IsBoostLinkEffectActiveGetAmount();
			num += num2;
		}
		OnUpdateDrawAmountText.Raise("+" + Mathf.Max(num + drawDicesAmount, 0));
		return Mathf.Max(num + drawDicesAmount, 0);
	}

	public int GetDrawDicesAmountWithModifiersForDescription()
	{
		return GetDrawDiceAmountWithOmensModifiers();
	}

	public void SetDefaultDrawDicesAmount()
	{
		drawDicesAmount = DefaultDrawDicesAmount;
		drawDicesAmountModifier = 0;
	}

	public void UpdateDrawDicesAmount(int amount)
	{
		drawDicesAmount += amount;
		GetDrawDiceAmountWithOmensModifiers();
	}

	public int GetDiceByNameAmount(string diceName, bool exactName)
	{
		List<Dice> list = new List<Dice>();
		if (ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.PlayerRewardState || ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.MapState)
		{
			list.AddRange(ReferenceSingleton<AssetsReference>.Instance.DicePool.GetAllDices());
		}
		else
		{
			list.AddRange(ReferenceSingleton<AssetsReference>.Instance.DrawPool.GetAllDices());
			list.AddRange(ReferenceSingleton<AssetsReference>.Instance.Discard.GetAllDices());
			for (int i = 0; i < HandDicePreview.Count; i++)
			{
				list.Add(HandDicePreview[i]);
			}
		}
		int num = 0;
		for (int j = 0; j < list.Count; j++)
		{
			Dice dice = list[j];
			if (exactName)
			{
				if (dice.DiceName.ToLower() == diceName.ToLower())
				{
					num++;
				}
			}
			else if (dice.DiceName.ToLower().Contains(diceName.ToLower()))
			{
				num++;
			}
		}
		return num;
	}

	public Dictionary<string, int> GetDiceByTypeAmount(bool onlyFromHand, bool onlyFromDicePool = false)
	{
		List<Dice> list = new List<Dice>();
		if (!onlyFromDicePool)
		{
			if (ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.PlayerRewardState || ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.MapState)
			{
				list.AddRange(ReferenceSingleton<AssetsReference>.Instance.DicePool.GetAllDices());
			}
			else
			{
				if (!onlyFromHand)
				{
					list.AddRange(ReferenceSingleton<AssetsReference>.Instance.DrawPool.GetAllDices());
					list.AddRange(ReferenceSingleton<AssetsReference>.Instance.Discard.GetAllDices());
				}
				for (int i = 0; i < HandDicePreview.Count; i++)
				{
					list.Add(HandDicePreview[i]);
				}
			}
		}
		else
		{
			list.AddRange(ReferenceSingleton<AssetsReference>.Instance.DicePool.GetAllDices());
		}
		Dictionary<string, int> dictionary = new Dictionary<string, int>
		{
			{ "Starter", 0 },
			{ "Safe", 0 },
			{ "Balanced", 0 },
			{ "Risky", 0 },
			{ "Epic", 0 },
			{ "Enchantment", 0 },
			{ "Purification", 0 },
			{ "Tactical", 0 },
			{ "Hex", 0 },
			{ "Debug", 0 }
		};
		for (int j = 0; j < list.Count; j++)
		{
			Dice dice = list[j];
			if (dice == null)
			{
				Debug.Log("GetDiceByTypeAmount DIE NULL");
			}
			else if ((bool)dice.DiceTier)
			{
				dictionary[dice.DiceTier.name]++;
			}
		}
		return dictionary;
	}

