			{ "Debug", 0 }
		};
		for (int j = 0; j < list.Count; j++)
		{
			Dice dice = list[j];
			if (dice == null)
			{
				Debug.Log("GetDiceByTypeAmountOnlyFromHand DIE NULL");
			}
			else if ((bool)dice.DiceTier)
			{
				dictionary[dice.DiceTier.name]++;
			}
		}
		return dictionary;
