	public List<Dice> GetAllNonHexDices()
	{
		List<Dice> list = new List<Dice>();
		if (ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.PlayerRewardState || ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.MapState)
		{
			list.AddRange(ReferenceSingleton<AssetsReference>.Instance.DicePool.GetAllDices());
		}
		else
		{
			list.AddRange(ReferenceSingleton<AssetsReference>.Instance.DrawPool.GetAllDices());
			list.AddRange(ReferenceSingleton<AssetsReference>.Instance.Discard.GetAllDices());
			for (int i = 0; i < HandDicePreview.Count; i++)
			{
				list.Add(HandDicePreview[i]);
			}
		}
		list.RemoveAll((Dice die) => die.DiceTier == ReferenceSingleton<AssetsReference>.Instance.HexDieTier);
		return list;
	}

	public int GetAmountOfActions(BattleAction battleAction, bool onlyFromHand, bool onlyFromDicePool = false)
	{
		List<Dice> list = new List<Dice>();
		if (!onlyFromDicePool)
		{
			if (ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.PlayerRewardState || ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.MapState)
			{
				list.AddRange(ReferenceSingleton<AssetsReference>.Instance.DicePool.GetAllDices());
			}
			else
			{
				if (!onlyFromHand)
				{
					list.AddRange(ReferenceSingleton<AssetsReference>.Instance.DrawPool.GetAllDices());
					list.AddRange(ReferenceSingleton<AssetsReference>.Instance.Discard.GetAllDices());
				}
				for (int i = 0; i < HandDicePreview.Count; i++)
				{
					list.Add(HandDicePreview[i]);
				}
			}
		}
		else
		{
			list.AddRange(ReferenceSingleton<AssetsReference>.Instance.DicePool.GetAllDices());
		}
		int num = 0;
		for (int j = 0; j < list.Count; j++)
		{
			Dice dice = list[j];
			if (dice == null)
			{
				Debug.Log("GetDiceByTypeAmount DIE NULL");
				continue;
			}
			for (int k = 0; k < dice.GetDiceFaces().Length; k++)
			{
				if (dice.GetDiceFaces()[k].BattleAction == battleAction)
				{
					num++;
				}
			}
		}
		return num;
	}

	public void TogglePlayerActionValueModifier(ActionValueModifier actionValueModifier)
	{
		ActionValueModifier actionValueModifier2 = GetActionValueModifier(actionValueModifier.BattleActionInteractionEnum);
		if (actionValueModifier2 == null)
		{
			actionValueModifiers.Add(actionValueModifier);
		}
		else
		{
			actionValueModifier2.ActionValueModifierAmount = actionValueModifier.ActionValueModifierAmount;
		}
		for (int i = 0; i < handDices.Count; i++)
		{
			handDices[i].Dice.ToggleActionValueModifier(actionValueModifiers);
			handDices[i].UpdateDiceFace();
		}
	}

	private ActionValueModifier GetActionValueModifier(BattleActionInteractionEnum battleActionInteractionEnum)
	{
		for (int i = 0; i < actionValueModifiers.Count; i++)
		{
			if (actionValueModifiers[i].BattleActionInteractionEnum == battleActionInteractionEnum)
			{
				return actionValueModifiers[i];
			}
		}
		return null;
	}

	public void UpdateActionValueModifier()
	{
		for (int i = 0; i < actionValueModifiers.Count; i++)
		{
			TogglePlayerActionValueModifier(actionValueModifiers[i]);
		}
	}

	public bool IsAnyPurifyCorruptAction(bool corrupt)
	{
		for (int i = 0; i < handDices.Count; i++)
		{
			if (corrupt)
			{
				if (handDices[i].ActionFace.BattleAction is CorruptAction)
				{
					return true;
				}
				if (handDices[i].ActionFace.EnableSecondAction && handDices[i].ActionFace.SecondBattleAction is CorruptAction)
				{
					return true;
				}
			}
			else
			{
				if (handDices[i].ActionFace.BattleAction is PurifyAction)
				{
					return true;
				}
				if (handDices[i].ActionFace.EnableSecondAction && handDices[i].ActionFace.SecondBattleAction is PurifyAction)
				{
					return true;
				}
			}
		}
		return false;
	}

	public bool IsAnyMustUseDice()
	{
		for (int i = 0; i < handDices.Count; i++)
		{
			if (CheckIfHandContainsInteractions(handDices[i]))
			{
				"Player hand has at least 1 must use action".DebugLogIfVerbose(verbose);
				return true;
			}
		}
		"Player hand has no must use action".DebugLogIfVerbose(verbose);
		return false;
	}

	private bool CheckIfHandContainsInteractions(DiceInstance diceInstance)
	{
		return diceInstance.ActionFace.BattleAction.BaseBattleActionData.HasMandatoryBattleActionInteractionEnum();
	}

	public bool IsAnyNonMustUseDice()
	{
		for (int i = 0; i < handDices.Count; i++)
		{
			if (!CheckIfHandContainsInteractions(handDices[i]))
			{
				"Player hand has at least 1 non must use action".DebugLogIfVerbose(verbose);
				return true;
			}
		}
		"Player hand has no non must use action".DebugLogIfVerbose(verbose);
		return false;
	}

	public bool IsAtLeastTwoNonMustUseDice()
	{
		int num = 0;
		for (int i = 0; i < handDices.Count; i++)
		{
			if (!CheckIfHandContainsInteractions(handDices[i]))
			{
				num++;
				if (num == 2)
				{
					return true;
				}
			}
		}
		return false;
	}

	public bool IsAnyPlayableNonMustUseActions()
	{
		for (int i = 0; i < handDices.Count; i++)
		{
			BattleAction battleAction = handDices[i].ActionFace.BattleAction;
			if (!CheckIfHandContainsInteractions(handDices[i]) && battleAction.CheckConditionToBeCasted(playerHand: true, DiceOwnerEnum.PLAYER))
			{
				"Player hand has at least 1 Playable Non Must Use use action".DebugLogIfVerbose(verbose);
				return true;
			}
		}
		"Player hand has no Playable Non Must Use use action".DebugLogIfVerbose(verbose);
		return false;
	}

	public bool IsAtLeastTwoNonHexDice()
	{
		int num = 0;
		for (int i = 0; i < handDices.Count; i++)
		{
			if (handDices[i].Dice.DiceTier != ReferenceSingleton<AssetsReference>.Instance.HexDieTier)
			{
				num++;
				if (num == 2)
				{
					return true;
				}
			}
		}
		return false;
	}

	public bool IsAnyPlayableNonHexActions()
	{
		for (int i = 0; i < handDices.Count; i++)
		{
			if (handDices[i].Dice.DiceTier != ReferenceSingleton<AssetsReference>.Instance.HexDieTier)
			{
				return true;
			}
		}
		return false;
	}
}
